∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {𝕜 : Type u_3} {G : Type u_4}
  [inst_2 : NontriviallyNormedField 𝕜] [IsRCLikeNormedField 𝕜] [inst_4 : NormedSpace 𝕜 E]
  [inst_5 : NormedAddCommGroup G] [inst_6 : NormedSpace 𝕜 G] {f : E → G} {C : ℝ} {s : Set E} {x y : E}
  {f' : E → E →L[𝕜] G},
  (∀ x ∈ s, HasFDerivWithinAt f (f' x) s x) →
    (∀ x ∈ s, ‖f' x‖ ≤ C) → Convex ℝ s → x ∈ s → y ∈ s → ‖f y - f x‖ ≤ C * ‖y - x‖

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {𝕜 : Type u_3} {G : Type u_4}
  [inst_2 : NontriviallyNormedField 𝕜] [IsRCLikeNormedField 𝕜] [inst_4 : NormedSpace 𝕜 E]
  [inst_5 : NormedAddCommGroup G] [inst_6 : NormedSpace 𝕜 G] {f : E → G} {C : ℝ} {s : Set E} {x y : E}
  {f' : E → E →L[𝕜] G} {φ : E →L[𝕜] G},
  (∀ x ∈ s, HasFDerivWithinAt f (f' x) s x) →
    (∀ x ∈ s, ‖f' x - φ‖ ≤ C) → Convex ℝ s → x ∈ s → y ∈ s → ‖f y - f x - φ (y - x)‖ ≤ C * ‖y - x‖

∀ {𝕜 : Type u_3} {G : Type u_4} [inst : RCLike 𝕜] [inst_1 : NormedAddCommGroup G] [inst_2 : NormedSpace 𝕜 G] {f : 𝕜 → G}
  {s : Set 𝕜} {x y : 𝕜} {C : ℝ},
  DifferentiableOn 𝕜 f s → (∀ x ∈ s, ‖derivWithin f s x‖ ≤ C) → Convex ℝ s → x ∈ s → y ∈ s → ‖f y - f x‖ ≤ C * ‖y - x‖

∀ {𝕜 : Type u_3} {G : Type u_4} [inst : RCLike 𝕜] [inst_1 : NormedAddCommGroup G] [inst_2 : NormedSpace 𝕜 G] {f : 𝕜 → G}
  {s : Set 𝕜} {C : NNReal},
  Convex ℝ s → DifferentiableOn 𝕜 f s → (∀ x ∈ s, ‖derivWithin f s x‖₊ ≤ C) → LipschitzOnWith C f s

∀ {𝕜 : Type u_3} {G : Type u_4} [inst : RCLike 𝕜] [inst_1 : NormedAddCommGroup G] [inst_2 : NormedSpace 𝕜 G] {f : 𝕜 → G}
  {s : Set 𝕜} {C : NNReal},
  (∀ x ∈ s, DifferentiableAt 𝕜 f x) → (∀ x ∈ s, ‖deriv f x‖₊ ≤ C) → Convex ℝ s → LipschitzOnWith C f s

∀ {𝕜 : Type u_3} {G : Type u_4} [inst : RCLike 𝕜] [inst_1 : NormedAddCommGroup G] [inst_2 : NormedSpace 𝕜 G] {f : 𝕜 → G}
  {s : Set 𝕜},
  IsOpen s → IsPreconnected s → DifferentiableOn 𝕜 f s → Set.EqOn (deriv f) 0 s → ∀ {x y : 𝕜}, x ∈ s → y ∈ s → f x = f y
